WITH цит AS (SELECT c1.entity_name AS история, trim(both '`' from trim(c1.value)) AS имя, c2.value AS цитата FROM project_document_cells c1 JOIN project_document_cells c2 ON c2.project_id = c1.project_id AND c2.entity_kind = c1.entity_kind AND c2.entity_name = c1.entity_name AND c2.block_ord = c1.block_ord AND c2.row_ord = c1.row_ord AND c2.col = 1 WHERE c1.project_id = $1 AND c1.entity_kind = 'story' AND c1.col = 0 AND c1.value ~ '^`?(FR-[A-Z]+-[0-9]+|NFR-[0-9]+)`?$'), норм AS (SELECT ц.история, ц.имя, lower(trim(regexp_replace(regexp_replace(ц.цитата, '[`*«»"]', '', 'g'), '\s+', ' ', 'g'))) AS сказано, lower(trim(regexp_replace(regexp_replace(coalesce(nullif(r.text, ''), r.title, ''), '[`*«»"]', '', 'g'), '\s+', ' ', 'g'))) AS источник FROM цит ц LEFT JOIN project_requirements r ON r.project_id = $1 AND r.id = ц.имя) SELECT история || ' → ' || имя || ': цитата разошлась с источником' AS detail FROM норм WHERE источник <> '' AND rtrim(сказано, '.') <> rtrim(источник, '.') UNION ALL SELECT история || ' → ' || имя || ': цитируется требование, которого нет' FROM норм WHERE источник = '' ORDER BY 1
